import sys

def main() -> None:
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    codes = data[1:1 + n]
    prev = bytearray(b"AAAAA")
    have = [0] * 26
    for idx in range(n):
        code = codes[idx]
        for t in range(26):
            have[t] = 0
        for ch in code:
            have[ch - 65] += 1
        # copy the previous sigil letter for letter while the letters are in stock
        cut = 0
        while cut < 5:
            t = prev[cut] - 65
            if have[t] == 0:
                break
            have[t] -= 1
            cut += 1
        forged = None
        while True:
            if cut == 5:
                forged = bytes(prev)
                break
            pick = -1
            for t in range(prev[cut] - 64, 26):
                if have[t] > 0:
                    pick = t
                    break
            if pick >= 0:
                have[pick] -= 1
                tail = bytearray()
                for t in range(26):
                    c = have[t]
                    if c > 0:
                        tail += bytes([65 + t]) * c
                forged = bytes(prev[:cut]) + bytes([65 + pick]) + bytes(tail)
                break
            if cut == 0:
                break
            cut -= 1
            have[prev[cut] - 65] += 1
        if forged is None:
            sys.stdout.write("-1\n")
            return
        prev = bytearray(forged)
    sys.stdout.write(prev.decode() + "\n")

main()
